mapper.select:
SELECT d.id,d.rental_order_id orderId,o.order_no orderNo,NULL goodsPaidFen,NULL goodsRefundedFen,NULL goodsBaseFen,NULL factoryGoodsFen,d.initial_rent_paid_amount_fen initialRentFen,d.shared_coupon_discount_amount_fen couponDiscountFen,d.extension_rent_paid_amount_fen extensionRentFen,d.overdue_rent_amount_fen overdueRentFen,d.overdue_commission_amount_fen overdueCommissionFen,d.rent_refunded_amount_fen rentRefundedFen,d.rent_settlement_adjustment_amount_fen rentAdjustmentFen,d.rent_settle_base_amount_fen rentBaseFen,d.commission_rate_bps commissionRateBps,d.platform_commission_amount_fen commissionFen,d.factory_rent_income_amount_fen factoryRentFen,d.deposit_compensation_amount_fen depositCompensationFen,d.excess_compensation_paid_amount_fen excessCompensationFen,d.freight_approved_amount_fen freightApprovedFen,d.freight_refunded_amount_fen freightRefundedFen,d.freight_reimbursement_amount_fen freightSettleFen,d.factory_settle_amount_fen factorySettleFen,d.detail_status status FROM factory_settlement_detail d JOIN rental_order o ON o.id=d.rental_order_id WHERE d.settlement_batch_id=#{id} UNION ALL SELECT d.id,o.id,o.custom_order_no,
    d.goods_paid_amount_fen,d.goods_refunded_amount_fen,d.goods_settle_base_amount_fen,d.factory_goods_income_fen,
    0,0,0,0,0,0,0,0,d.commission_rate_bps,d.platform_commission_amount_fen,0,0,0,
    o.delivery_fee_paid_fen,o.delivery_fee_paid_fen-d.delivery_fee_settle_fen,d.delivery_fee_settle_fen,d.factory_settle_amount_fen,d.settlement_status
    FROM custom_order_settlement d JOIN custom_order o ON o.id=d.custom_order_id WHERE d.settlement_batch_id=#{id}
    ORDER BY id LIMIT #{page.pageSize} OFFSET #{page.offset}

SELECT id,COALESCE(settlement_detail_id,custom_settlement_id) detailId,payment_channel_suborder_id sourceSuborderId,execution_type type,commission_status commissionStatus,unfreeze_status unfreezeStatus,platform_commission_amount_fen expectedCommissionFen,actual_commission_amount_fen actualCommissionFen,factory_unlock_amount_fen expectedUnlockFen,actual_unlock_amount_fen actualUnlockFen,channel_sharing_no channelSharingNo,channel_finish_no channelFinishNo,exception_code exceptionCode,
    CONCAT(LEFT(DATE_FORMAT(last_queried_at,'%Y-%m-%dT%H:%i:%s.%f'),23),'+08:00') lastQueriedAt,CONCAT(LEFT(DATE_FORMAT(success_at,'%Y-%m-%dT%H:%i:%s.%f'),23),'+08:00') successAt
    FROM wechat_profit_sharing_order WHERE settlement_batch_id=#{id} ORDER BY id LIMIT #{page.pageSize} OFFSET #{page.offset}

SELECT h FROM (
    SELECT 'i' kind,id,SHA2(JSON_ARRAY(id,detail_status,rent_settle_base_amount_fen,platform_commission_amount_fen,factory_settle_amount_fen,source_allocation_snapshot_json),256) h FROM factory_settlement_detail WHERE settlement_batch_id=#{id}
    UNION ALL SELECT 'c',id,SHA2(JSON_ARRAY(id,settlement_status,goods_settle_base_amount_fen,platform_commission_amount_fen,factory_settle_amount_fen),256) FROM custom_order_settlement WHERE settlement_batch_id=#{id}
    UNION ALL SELECT 'w',id,SHA2(JSON_ARRAY(id,version,commission_status,unfreeze_status,actual_commission_amount_fen,actual_unlock_amount_fen,exception_code),256) FROM wechat_profit_sharing_order WHERE settlement_batch_id=#{id}
    UNION ALL SELECT 'p',id,SHA2(JSON_ARRAY(id,payment_status,payable_amount_fen,actual_paid_amount_fen,receiver_account_masked_snapshot),256) FROM factory_settlement_payment WHERE settlement_batch_id=#{id}
    ) facts ORDER BY kind,id
